import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/mte2_overlap.CDst60Zg.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核内同步","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync"},{"text":"Lock","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/Lock"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/Lock.md","filePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/Lock.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),t={name:"api/SIMD-API/basic_api/sync_control/intra_core_sync/Lock.md"};function e(o,s,i,d,r,h){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>Lock<span id="ZH-CN_TOPIC_0000002372961532"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section73648168211"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section54681522111017"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_common.h&quot;</code>。</p><p>根据MutexID获取Mutex，若Mutex已被锁定，将阻塞指定流水上后续指令的执行，直到所有流水中具有相同MutexID的Mutex都已经被<a href="Unlock.html">Unlock</a>释放。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>Lock接口需与<a href="Unlock.html">Unlock</a>接口配合使用，对同一个MutexID，Lock和Unlock必须严格成对出现，否则属于未定义行为。具体约束请参见<a href="#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">约束说明</a>。</p></div><h2 id="函数原型">函数原型<span id="section1568410468104"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="o">&gt;</span>
<span class="k">static</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Lock</span><span class="p">(</span><span class="n">MutexID</span><span class="w"> </span><span class="n">id</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section74061251191017"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>pipe</td><td>模板参数，表示流水类别。支持PIPE_S、PIPE_M、PIPE_V、PIPE_MTE1、PIPE_MTE2、PIPE_MTE3、PIPE_FIX，各流水类型的含义请参考<a href="intra_core_sync_overview.html#%E7%A1%AC%E4%BB%B6%E6%B5%81%E6%B0%B4%E7%B1%BB%E5%9E%8B">硬件流水类型</a>。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>id</td><td>输入</td><td>进行流水同步管理的MutexID。在不同编程范式中，该ID的获取以及释放方式不同，详细情况参考<a href="#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">约束说明</a>。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section184751024101111"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>每个锁有固定的一个MutexID，在不同编程范式中，该ID的获取以及释放方式不同：</p><ul><li>采用<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/tpipe_tque_programming/tpipe_tque_paradigm.html">TPipe-TQue框架编程范式</a>时，MutexID需要通过<a href="AllocMutexID_ISASI.html">AllocMutexID</a>/<a href="ReleaseMutexID_ISASI.html">ReleaseMutexID</a>进行申请释放。</li><li>采用<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/static_tensor_programming.html">静态Tensor编程范式</a>时，MutexID由开发者自行管理，建议使用0-27，28-31为系统内部规划预留，不建议使用。</li></ul></li><li><p>Lock与Unlock必须严格成对使用，并使用相同的pipe和id。此外，对应的Unlock必须始终写在Lock之后，否则属于未定义行为。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 反例：先Unlock再Lock，顺序颠倒。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
</code></pre></div></li><li><p>对于id相同的Lock与Unlock组合，无论pipe是否相同，都不得在代码中嵌套使用，否则属于未定义行为。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 反例：id相同，Lock与Unlock嵌套。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
</code></pre></div></li><li><p>当具有相同id与pipe的两对Lock与Unlock连续调用时，第一次调用的Lock将由参数pipe指定的流水阻塞后，第二次调用的Lock不能再次阻塞该流水。换言之，连续调用的、具有相同id与pipe的两对Lock与Unlock不能实现单流水（参数pipe指定）内不同指令之间的同步，单流水内多个指令之间的同步请使用<a href="PipeBarrier_ISASI.html">PipeBarrier</a>接口。</p><p>如<a href="#fig_mte2_overlap">图1</a>所示，两次搬运的目的地址在Unified Buffer（UB）存在重叠时，开发者需要控制PIPE_MTE2上两条指令执行的先后顺序。在此场景中如下写法（具有相同id与pipe的两对Lock与Unlock连续调用）只能保证两条PIPE_MTE2上指令执行后，PIPE_V上指令才能执行，但并不能控制PIPE_MTE2上两条指令执行的先后顺序，正确写法是在<code>CopyInY</code>与<code>CopyInX</code>之间插入<code>PipeBarrier&lt;PIPE_MTE2&gt;()</code>。</p><p><strong>图1</strong> PIPE_MTE2上两次搬运目的地址（UB）存在重叠 <span id="fig_mte2_overlap"></span><br><img src="`+c+`" alt></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// x和y在UB上的地址存在重叠（重叠部分x覆盖y），预期先搬入y后搬入x，需要保证搬入顺序。</span>
<span class="kt">void</span><span class="w"> </span><span class="nf">CopyInX</span><span class="p">(</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">xGm</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">len</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutexId</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">xGm</span><span class="p">,</span><span class="w"> </span><span class="n">len</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="p">}</span>

<span class="kt">void</span><span class="w"> </span><span class="nf">CopyInY</span><span class="p">(</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">yGm</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">len</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutexId</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">yGm</span><span class="p">,</span><span class="w"> </span><span class="n">len</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="p">}</span>

<span class="kt">void</span><span class="w"> </span><span class="nf">Process</span><span class="p">(</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">len</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutexId</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 先搬入y，再搬入x（重叠部分x覆盖y），顺序错误会导致精度异常。</span>
<span class="w">    </span><span class="n">CopyInY</span><span class="p">(</span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">yGm</span><span class="p">,</span><span class="w"> </span><span class="n">len</span><span class="p">,</span><span class="w"> </span><span class="n">mutexId</span><span class="p">);</span>

<span class="w">    </span><span class="cm">/*</span>
<span class="cm">    * // 必须在CopyInY与CopyInX之间插入PipeBarrier，保证前一次搬入完成后才执行下一次搬入。</span>
<span class="cm">    * AscendC::PipeBarrier&lt;PIPE_MTE2&gt;();</span>
<span class="cm">    */</span>

<span class="w">    </span><span class="n">CopyInX</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">xGm</span><span class="p">,</span><span class="w"> </span><span class="n">len</span><span class="p">,</span><span class="w"> </span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">len</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></li></ul><h2 id="调用示例">调用示例<span id="section123275308128"></span><a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 申请两个MutexID，供双缓冲流水交替复用。</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutexId0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">AllocMutexID</span><span class="p">();</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutexId1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">AllocMutexID</span><span class="p">();</span>

<span class="c1">// 交替使用两个MutexID，保证MTE2、V、MTE3三段流水按顺序串联。</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">loopCount</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutexId</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">i</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">mutexId0</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">mutexId1</span><span class="p">;</span>

<span class="w">    </span><span class="c1">// 锁住MTE2流水，保证当前tile的搬入按该MutexID顺序执行。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">src0Global</span><span class="p">[</span><span class="n">TILE_LENGTH</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">progress</span><span class="p">],</span><span class="w"> </span><span class="n">TILE_LENGTH</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">src1Global</span><span class="p">[</span><span class="n">TILE_LENGTH</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">progress</span><span class="p">],</span><span class="w"> </span><span class="n">TILE_LENGTH</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 搬入完成后解锁MTE2流水，允许后续阶段继续推进。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 锁住V流水，等待对应tile的搬入完成后再开始计算。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">TILE_LENGTH</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 计算完成后解锁V流水，放行后续计算或搬出。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 锁住MTE3流水，确保计算结果完成后再写回GM。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">[</span><span class="n">TILE_LENGTH</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">progress</span><span class="p">],</span><span class="w"> </span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">TILE_LENGTH</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 搬出完成后解锁MTE3流水，结束当前tile的处理。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="p">}</span>

<span class="c1">// 释放本次样例申请的两个MutexID。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">ReleaseMutexID</span><span class="p">(</span><span class="n">mutexId0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">ReleaseMutexID</span><span class="p">(</span><span class="n">mutexId1</span><span class="p">);</span>
</code></pre></div><p>完整样例请参考：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/05_sync_control/mutex">Mutex样例</a>。</p></article></div>`,1)])])}const w=a(t,[["render",e]]);export{u as __pageData,w as default};
